from pathlib import Path
import json,shutil
ROOT=Path(__file__).resolve().parents[2]
BACK=ROOT/'scratch/order-lifecycle-before-20261029';BACK.mkdir(exist_ok=True)
paths=['artifacts/requirements/software-requirements-specification.md','artifacts/requirements/business-rules.md','artifacts/requirements/business-rules.csv','artifacts/requirements/customer-use-case-descriptions.md','artifacts/design/database-design.md','artifacts/diagrams/class/entity-class-diagram.drawio','artifacts/diagrams/database/physical-erd.drawio','artifacts/Requirements_Analysis_Design_Specification.docx','artifacts/requirements/Software_Requirements_Specification.docx','artifacts/traceability/Requirements_Traceability_Matrix.xlsx']
for rel in paths:
 p=ROOT/rel
 if p.exists():
  b=BACK/rel;b.parent.mkdir(parents=True,exist_ok=True)
  if not b.exists():shutil.copy2(p,b)
tables=[]
def table(name,entity,basis,cols,checks=()):tables.append(dict(name=name,entity=entity,basis=basis,columns=[dict(name=n,type=t,constraint=c,description=d) for n,t,c,d in cols],checks=list(checks)))
ID=('id','BIGINT','GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY','Technical surrogate identifier')
# Each new field traces to receiving, payment evidence, fault-based fees or staff disposition.
table('delivery_agents','DeliveryAgent','FR-DEL-01; customer instruction to pay the delivery agent',[
 ('delivery_agent_id',*ID[1:]),('display_name','VARCHAR(120)','NOT NULL','Assigned delivery agent identity'),('contact_phone','VARCHAR(30)','','Operational contact; nullable until known')])
table('order_payments','OrderPayment','FR-PAY-03; verified payment and separate shipping-fee collection',[
 ('payment_id',*ID[1:]),('order_id','BIGINT','NOT NULL REFERENCES orders(order_id)','Order whose receipt is allocated'),('payment_channel','VARCHAR(30)','NOT NULL','VIETQR, COD or SHIPPING_FEE_CASH'),('provider_transaction_id','VARCHAR(120)','NOT NULL','Verified receipt/cash evidence reference; deduplicated per channel'),('goods_amount','NUMERIC(18,0)','NOT NULL CHECK (goods_amount >= 0)','Actual collected net goods amount in VND'),('shipping_amount','NUMERIC(18,0)','NOT NULL CHECK (shipping_amount >= 0)','Actual collected delivery fee in VND'),('unallocated_amount','NUMERIC(18,0)','NOT NULL DEFAULT 0 CHECK (unallocated_amount>=0)','Verified excess amount not assigned to goods/shipping; refund policy TBD'),('captured_amount','NUMERIC(18,0)','GENERATED ALWAYS AS (goods_amount + shipping_amount + unallocated_amount) STORED','Derived total captured receipt; must match verified original payment evidence'),('received_at','TIMESTAMPTZ','NOT NULL','Confirmed collection time'),('recorded_by_staff_id','INT','REFERENCES staff_accounts(staff_id)','Staff recording cash evidence; gateway receipts may have no staff'),('collected_by_delivery_agent_id','BIGINT','REFERENCES delivery_agents(delivery_agent_id)','Actual delivery agent collecting cash; not a store staff role')],['goods_amount + shipping_amount > 0',"payment_channel IN ('VIETQR','COD','SHIPPING_FEE_CASH')", "payment_channel <> 'SHIPPING_FEE_CASH' OR (goods_amount=0 AND collected_by_delivery_agent_id IS NOT NULL)"])
table('delivery_failures','DeliveryFailure','FR-DEL-03/05; fault-based shipping policy',[
 ('failure_id',*ID[1:]),('order_id','BIGINT','NOT NULL UNIQUE REFERENCES orders(order_id)','One current failed-delivery record in the specified full-return scope'),('failure_cause','VARCHAR(40)',"NOT NULL DEFAULT 'UNCLASSIFIED'",'UNCLASSIFIED, PRODUCT_FAULT, CUSTOMER_INTENTIONAL_REFUSAL or OTHER'),('reason','TEXT',"NOT NULL CHECK (length(trim(reason))>0)",'Observed reason; no automatic inference of deliberate refusal'),('reported_by_staff_id','INT','NOT NULL REFERENCES staff_accounts(staff_id)','Sales Staff recording the delivery outcome'),('reported_at','TIMESTAMPTZ','NOT NULL DEFAULT CURRENT_TIMESTAMP','Failure recording time'),('cause_confirmed_by_staff_id','INT','REFERENCES staff_accounts(staff_id)','Final cause decision identity; authority policy TBD'),('cause_confirmed_at','TIMESTAMPTZ','','Final cause decision time'),('cause_evidence','TEXT','','Evidence for review; separate from warehouse quality decision')],["failure_cause IN ('UNCLASSIFIED','PRODUCT_FAULT','CUSTOMER_INTENTIONAL_REFUSAL','OTHER')",'(cause_confirmed_by_staff_id IS NULL) = (cause_confirmed_at IS NULL)',"cause_confirmed_at IS NULL OR failure_cause <> 'UNCLASSIFIED'"])
table('return_receipts','ReturnReceipt','FR-DEL-04; complete physical warehouse receipt before refund',[
 ('return_receipt_id',*ID[1:]),('order_id','BIGINT','NOT NULL UNIQUE REFERENCES orders(order_id)','One full-return receipt obligation per order; partial facts remain draft'),('receipt_status','VARCHAR(16)',"NOT NULL DEFAULT 'DRAFT'",'DRAFT or COMPLETE; only complete line matching unlocks the full-return path'),('created_by_staff_id','INT','NOT NULL REFERENCES staff_accounts(staff_id)','Warehouse receiving staff'),('created_at','TIMESTAMPTZ','NOT NULL DEFAULT CURRENT_TIMESTAMP','Receipt creation time'),('confirmed_by_staff_id','INT','REFERENCES staff_accounts(staff_id)','Warehouse Staff confirming all goods physically received'),('confirmed_at','TIMESTAMPTZ','','Complete receipt confirmation time')],["receipt_status IN ('DRAFT','COMPLETE')","receipt_status <> 'COMPLETE' OR (confirmed_by_staff_id IS NOT NULL AND confirmed_at IS NOT NULL)"])
table('return_receipt_items','ReturnReceiptItem','FR-DEL-04; match quantities to original batch-bearing order lines',[
 ('return_receipt_item_id',*ID[1:]),('return_receipt_id','BIGINT','NOT NULL','Receipt, with order ownership enforced by composite FK'),('order_id','BIGINT','NOT NULL','Order ownership key; technical integrity support'),('order_detail_id','BIGINT','NOT NULL','Original order line and original batch reference'),('quantity_received','INT','NOT NULL CHECK (quantity_received>0)','Physical quantity actually received; incomplete totals do not mean complete')])
table('return_inspections','ReturnInspection','FR-DEL-07; staff-only quality and disposition decisions',[
 ('inspection_id',*ID[1:]),('return_receipt_item_id','BIGINT','NOT NULL REFERENCES return_receipt_items(return_receipt_item_id)','Physical returned line being assessed'),('inspected_by_staff_id','INT','NOT NULL REFERENCES staff_accounts(staff_id)','Actual staff assessor; no automated quality classification'),('inspected_at','TIMESTAMPTZ','NOT NULL','Staff assessment timestamp'),('quantity','INT','NOT NULL CHECK (quantity>0)','Quantity subject to this handling decision'),('disposition','VARCHAR(16)','NOT NULL','RESTOCK, HOLD or DISPOSE under existing warehouse authority'),('condition_notes','TEXT','NOT NULL','Observed condition and staff reasoning'),('inventory_applied_at','TIMESTAMPTZ','','When authorized inventory movement was committed; not automatic at receipt')],["disposition IN ('RESTOCK','HOLD','DISPOSE')"])
table('refunds','Refund','FR-PAY-04/05; automatic refund once receipt/payment and cause policy permit',[
 ('refund_id',*ID[1:]),('order_id','BIGINT','NOT NULL UNIQUE REFERENCES orders(order_id)','One idempotent full failed-delivery return refund obligation in current scope'),('return_receipt_id','BIGINT','NOT NULL UNIQUE','Complete physical receipt, with matching order FK'),('goods_amount','NUMERIC(18,0)','NOT NULL CHECK (goods_amount>=0)','Actual collected goods amount refunded'),('shipping_amount','NUMERIC(18,0)','NOT NULL CHECK (shipping_amount>=0)','Refund paid shipping only for confirmed product fault'),('refund_status','VARCHAR(16)',"NOT NULL DEFAULT 'PENDING'",'PENDING, PROCESSING, SUCCEEDED, FAILED or UNKNOWN; technical workflow'),('idempotency_key','VARCHAR(120)','NOT NULL UNIQUE','Technical guard against duplicate provider payout'),('requested_at','TIMESTAMPTZ','NOT NULL DEFAULT CURRENT_TIMESTAMP','Automatic refund obligation creation time'),('settled_at','TIMESTAMPTZ','','Verified outgoing settlement completion time'),('provider_refund_reference','VARCHAR(160)','UNIQUE','Actual verified payout reference; provider integration TBD')],['goods_amount+shipping_amount>0',"refund_status IN ('PENDING','PROCESSING','SUCCEEDED','FAILED','UNKNOWN')","refund_status <> 'SUCCEEDED' OR (settled_at IS NOT NULL AND provider_refund_reference IS NOT NULL)"])
table('shipping_fee_settlements','ShippingFeeSettlement','FR-DEL-06; waived/retained/collected customer fee and agent compensation',[
 ('shipping_settlement_id',*ID[1:]),('order_id','BIGINT','NOT NULL UNIQUE REFERENCES orders(order_id)','Failed-delivery fee obligation'),('delivery_agent_id','BIGINT','NOT NULL REFERENCES delivery_agents(delivery_agent_id)','Assigned payee; no new staff-account role is assumed'),('customer_fee_due','NUMERIC(18,0)','CHECK (customer_fee_due>=0)','Zero for product fault; original fee for deliberate refusal; NULL if unresolved'),('collection_payment_id','BIGINT','REFERENCES order_payments(payment_id)','Actual cash fee receipt if collected directly by agent'),('compensation_due_amount','NUMERIC(18,0)','CHECK (compensation_due_amount>=0)','Agreed delivery-agent compensation; product-fault payer/rate is unspecified'),('compensation_paid_amount','NUMERIC(18,0)','NOT NULL DEFAULT 0 CHECK (compensation_paid_amount>=0)','Actual amount paid/retained as compensation, not presumed collected'),('compensated_at','TIMESTAMPTZ','','Actual compensation completion time'),('settlement_reference','VARCHAR(160)','','Payout or direct cash-retention evidence')],['compensation_due_amount IS NULL OR compensation_paid_amount <= compensation_due_amount', 'compensation_paid_amount=0 OR (compensated_at IS NOT NULL AND settlement_reference IS NOT NULL)'])
order_additions=[
 ('delivery_agent_id','BIGINT','REFERENCES delivery_agents(delivery_agent_id)','Assigned courier/payee'),
 ('phone_confirmation_status','VARCHAR(24)',"NOT NULL DEFAULT 'NOT_CONTACTED'",'NOT_CONTACTED, CONFIRMED or UNCONFIRMED; mandatory only for first unpaid order'),
 ('phone_contacted_by_staff_id','INT','REFERENCES staff_accounts(staff_id)','Store staff performing phone confirmation'),
 ('phone_contacted_at','TIMESTAMPTZ','','Actual contact/attempt timestamp'),
 ('phone_confirmation_note','TEXT','','Result/reason; no invented retry count or timeout'),
 ('cancellation_reason','TEXT','','Customer/staff cancellation reason')]
model=dict(version='2.0',date='2026-10-29',status='Requested revision; design decisions for review',rdbms='PostgreSQL 16+',tables=tables,order_additions=[dict(name=n,type=t,constraint=c,description=d) for n,t,c,d in order_additions],rules={
'BR-ORD-01':'Only accept an order when every requested line has sufficient sellable on-hand stock less existing reservations. Reserve FEFO batches atomically with order creation; do not accept backorders.',
'BR-FUL-01':'Telephone confirmation is mandatory only for a first order whose goods payment is Unpaid. Store staff must obtain customer confirmation before approving that order; if confirmation cannot be obtained, staff may decide to cancel and release reservations. No automatic cancellation deadline or retry count is defined.',
'BR-FUL-04':'Record Delivery Failed separately from warehouse receipt. Warehouse Staff confirm all returned goods before Returned and the full-return refund path. Staff inspect goods and decide inventory disposition; the system records their decision. Inspection must not delay an otherwise eligible refund. Goods do not automatically become sellable on receipt.',
'BR-FUL-05':'For customer refusal due to product fault, the customer bears no delivery fee: refund captured goods and shipping amounts, or collect neither when unpaid. For confirmed deliberate refusal unrelated to product fault, refund captured goods only and retain the captured delivery fee for delivery-agent compensation; if goods were unpaid, the customer owes the delivery fee directly to the delivery agent. Record actual collection and compensation separately. Do not classify an unreachable customer as deliberate refusal automatically.',
'BR-FUL-06':'Automatic refund requires verified goods payment, confirmed complete physical return and a confirmed failure-cause category determining fee liability. Do not wait for warehouse quality inspection. Refund actual original collected allocations, not current prices. Provider request acceptance is not proof of completed refund. Unclassified/other causes remain unresolved; final cause-decision authority and payout integration are TBD.'},requirements={
'FR-ORD-03':'The system shall atomically validate and reserve sufficient sellable on-hand FEFO batch quantities for every order line while creating the order, rejecting the whole submission if any line is unavailable. Backorders are not accepted.',
'FR-MYO-01':'The system shall show Pending Unpaid and Pending Paid as independent initial order states, then Confirmed, Packing, Shipping, Delivered, Cancelled, Delivery Failed and Returned, together with independent goods-payment, refund and shipping-fee collection information.',
'FR-FUL-02':'The system shall require successful staff telephone confirmation before approving a first unpaid order. Paid first orders and repeat orders do not require that mandatory call. If the first unpaid order cannot be confirmed, store staff may cancel it with a recorded reason and release reservations.',
'FR-DEL-03':'The system shall record failed delivery, its evidence and cause separately from physical return receipt, preserving the goods-payment state. A recorded failure alone shall not make stock available or confirm a completed refund.',
'FR-DEL-04':'The system shall let Warehouse Staff record returned quantities against original order lines/batches and confirm complete receipt only when all shipped quantities match; incomplete receipts shall not enter the full-return refund path.',
'FR-DEL-05':'The system shall record the reported failure cause, evidence and final cause confirmer/time; product fault and deliberate customer refusal have different shipping-fee consequences. The authority allowed to confirm the cause is TBD; no automatic blame classification is allowed.',
'FR-DEL-06':'The system shall record customer shipping-fee liability, actual direct cash collection by the delivery agent, retained prepaid shipping fees and actual compensation paid to the agent separately. Shipping-only collection shall not mark goods as paid.',
'FR-DEL-07':'The system shall record staff quality assessments and inventory-disposition quantities for returned goods, with staff/time/evidence. It shall apply only authorized inventory changes, without making this assessment a prerequisite for the customer refund.',
'FR-PAY-03':'The system shall preserve verified payment receipts and their original goods/shipping allocations, channel and deduplication reference, and track goods-payment independently of fulfillment; select the initial Pending Unpaid or Pending Paid order state from verified payment at checkout, without a transition between these states.',
'FR-PAY-04':'For a paid fully received failed-delivery return with a confirmed cause, the system shall automatically refund actual collected goods plus shipping for product fault, or actual goods only for deliberate refusal. Unpaid goods have no prepaid goods refund; product-fault customers owe no shipping fee.',
'FR-PAY-05':'The system shall create at most one full-return refund obligation in the current scope, use idempotent payout references, track unresolved/failed payout separately, and mark partial/full refund only after verified settlement; outgoing integration remains TBD.'})
(ROOT/'artifacts/design/order-lifecycle-model.json').write_text(json.dumps(model,indent=2),encoding='utf-8')
print('Saved coordinated model:',len(tables),'new business entities/tables,',len(model['requirements']),'changed/new requirements.')
